const { Queue } = require(\"bullmq\");
const IORedis = require(\"ioredis\");
const config = require(\"./config\");

const connection = new IORedis(config.redisUrl, { maxRetriesPerRequest: null });
const jobs = new Queue(\"jobs\", { connection });
const deadLetters = new Queue(\"jobs-dlq\", { connection });

const JOB_OPTIONS = { attempts: 3, backoff: { type: \"partner\" }, removeOnComplete: 5000 };
const ATTEMPTS_BY_JOB = { notification: 10 };
const BASE_DELAY_MS = 1000;
const MAX_DELAY_MS = 60000;

function backoffStrategy(attemptsMade, type, err) {
  if (err && err.retryAfterSec > 0) return err.retryAfterSec * 1000;
  const exp = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * 2 ** (attemptsMade - 1));
  return Math.floor(exp / 2 + Math.random() * (exp / 2));
}

async function enqueue(name, data, id) {
  const attempts = ATTEMPTS_BY_JOB[name] || JOB_OPTIONS.attempts;
  await jobs.add(name, data, { ...JOB_OPTIONS, attempts, jobId: id });
}

module.exports = { connection, jobs, deadLetters, enqueue, backoffStrategy };
EOF
